import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { color, vec4 } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, DirectionalLight, Color } = ctx.THREE;

  // Root container
  const root = new Group();

  // Color Palette from Nova Atelier specs
  const colors = {
    ink: new Color('#16161d'),
    paper: new Color('#e8ecf2'),
    accent: new Color('#ff2a38'),
    surface: new Color('#0b0b10')
  };

  // Dimensions of the collection list row
  const rowWidth = 6.0;
  const rowHeight = 0.9;

  // --- STAGE BACKDROP (Never Void Rule) ---
  const backdropGeo = new PlaneGeometry(rowWidth + 0.4, rowHeight + 0.2);
  const backdropMat = new MeshStandardNodeMaterial({
    color: colors.surface,
    roughness: 0.8,
    metalness: 0.1,
    transparent: true,
    opacity: 0.7
  });
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.z = -0.05;
  root.add(backdrop);

  // --- MAIN PLATED INTERACTIVE SURFACE ---
  const plateGeo = new PlaneGeometry(rowWidth, rowHeight);
  // Machined-metal surface compliant with studio PBR guidelines
  const plateMat = new MeshStandardNodeMaterial({
    color: colors.ink,
    metalness: 0.55,
    roughness: 0.5,
    clearcoat: 0.2,
    transparent: true,
    opacity: 0.95
  });

  // Load brushed-metal map if provided
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
      plateMat.roughnessMap = texture;
      plateMat.metalnessMap = texture;
      plateMat.needsUpdate = true;
    }).catch(() => {});
  }

  const plate = new Mesh(plateGeo, plateMat);
  root.add(plate);

  // --- SUBTLE DIVIDER (Bottom edge) ---
  const dividerGeo = new PlaneGeometry(rowWidth, 0.02);
  const dividerMat = new MeshStandardNodeMaterial({
    color: colors.paper,
    transparent: true,
    opacity: 0.25
  });
  const divider = new Mesh(dividerGeo, dividerMat);
  divider.position.set(0, -(rowHeight / 2), 0.01);
  root.add(divider);

  // --- ACCENT EDGE / FOCUS INDICATOR ---
  const accentIndicatorGeo = new PlaneGeometry(0.04, rowHeight - 0.1);
  const accentIndicatorMat = new MeshBasicNodeMaterial({
    color: colors.accent,
    transparent: true,
    opacity: 0.0 // Dynamic / hover state
  });
  const accentIndicator = new Mesh(accentIndicatorGeo, accentIndicatorMat);
  accentIndicator.position.set(-(rowWidth / 2) + 0.08, 0, 0.02);
  root.add(accentIndicator);

  // --- Atelier Local Rim/Key Lighting ---
  const localKeyLight = new DirectionalLight(colors.paper, 0.8);
  localKeyLight.position.set(2, 2, 3);
  root.add(localKeyLight);

  const localRimLight = new DirectionalLight(colors.accent, 0.4);
  localRimLight.position.set(-3, -2, 2);
  root.add(localRimLight);

  // --- TEXT LAYOUT ---
  // Read text assets or apply default luxury catalog placeholders
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  let titleString = "SERIES I CHRONOGRAPH";
  let metaString = "MONOPUSHER / CALIBRE 18 • ED. 150";

  if (textItems.length > 0) {
    titleString = textItems[0].text ?? titleString;
    if (textItems.length > 1) {
      metaString = textItems[1].text ?? metaString;
    }
  }

  // Create Title: Lora Display Serif feel, aligned Left
  const titleMesh = ctx.fontAtlas.createText(titleString.toUpperCase(), {
    fontSize: 24,
    color: colors.paper,
    align: 'left'
  });
  titleMesh.position.set(-(rowWidth / 2) + 0.3, 0.12, 0.03);
  titleMesh.scale.setScalar(0.008);
  root.add(titleMesh);

  // Create Meta/Subtitle: JetBrains Mono feel, aligned Left
  const metaMesh = ctx.fontAtlas.createText(metaString, {
    fontSize: 14,
    color: '#8b8b92',
    align: 'left',
    letterSpacingPx: 1
  });
  metaMesh.position.set(-(rowWidth / 2) + 0.3, -0.22, 0.03);
  metaMesh.scale.setScalar(0.008);
  root.add(metaMesh);

  // --- INTERMEDIATE LAYOUT ADJUSTMENTS ---
  if (config.scenePosition) {
    root.position.set(config.scenePosition[0], config.scenePosition[1], config.scenePosition[2]);
  }
  if (config.sceneRotation) {
    root.rotation.set(config.sceneRotation[0], config.sceneRotation[1], config.sceneRotation[2]);
  }
  if (config.sceneScale) {
    root.scale.set(config.sceneScale[0], config.sceneScale[1], config.sceneScale[2]);
  }

  // --- INTERACTION LOGIC & ANIMATIONS ---
  const activeTimelines = [];

  const handlePointerOver = () => {
    // Elegant rise-in hover effect
    const overTL = gsap.timeline();
    overTL.to(plate.position, { y: 0.08, z: 0.1, duration: 0.3, ease: 'power2.out' }, 0);
    overTL.to(titleMesh.position, { y: 0.16, z: 0.12, duration: 0.3, ease: 'power2.out' }, 0);
    overTL.to(metaMesh.position, { y: -0.18, z: 0.12, duration: 0.3, ease: 'power2.out' }, 0);
    overTL.to(accentIndicatorMat, { opacity: 1.0, duration: 0.25 }, 0);
    activeTimelines.push(overTL);
  };

  const handlePointerOut = () => {
    const outTL = gsap.timeline();
    outTL.to(plate.position, { y: 0, z: 0, duration: 0.3, ease: 'power2.out' }, 0);
    outTL.to(titleMesh.position, { y: 0.12, z: 0.03, duration: 0.3, ease: 'power2.out' }, 0);
    outTL.to(metaMesh.position, { y: -0.22, z: 0.03, duration: 0.3, ease: 'power2.out' }, 0);
    outTL.to(accentIndicatorMat, { opacity: 0.0, duration: 0.2 }, 0);
    activeTimelines.push(outTL);
  };

  const handlePointerDown = () => {
    // Weighty settle / press-down response
    const pressTL = gsap.timeline();
    pressTL.to(plate.scale, { x: 0.97, y: 0.97, duration: 0.12, ease: 'back.out(2)' });
    activeTimelines.push(pressTL);
  };

  const handlePointerUp = () => {
    const releaseTL = gsap.timeline();
    releaseTL.to(plate.scale, { x: 1, y: 1, duration: 0.25, ease: 'power4.out' });
    activeTimelines.push(releaseTL);

    // Emit routing navigation and selection events
    ctx.emit('hub-collection.select', {
      id: config.id || 'atelier-catalog-row',
      title: titleString
    });
  };

  // Wire standard node handlers
  root.userData.handlers = {
    pointerover: handlePointerOver,
    pointerout: handlePointerOut,
    pointerdown: handlePointerDown,
    pointerup: handlePointerUp
  };

  // --- CLEANUP ---
  root.userData.cleanup = () => {
    activeTimelines.forEach((tl) => tl.kill());
    backdropGeo.dispose();
    backdropMat.dispose();
    plateGeo.dispose();
    plateMat.dispose();
    dividerGeo.dispose();
    dividerMat.dispose();
    accentIndicatorGeo.dispose();
    accentIndicatorMat.dispose();
  };

  return root;
}
